export const ordersRouter = Router();

ordersRouter.post('/orders', requireUser, async (req, res) => {
  if (!req.body.sku) return res.status(400).json({ error: 'sku required' });
  const order = await createOrder({ userId: req.user.id, sku: req.body.sku, quantity: req.body.quantity });
  return res.status(201).json(order);
});

test('rejects an order without a sku', async () => {
  const response = await request(app).post('/orders').send({ quantity: 2 });
  expect(response.status).toBe(400);
});
